        m, n = map(int, data[:2])
        values = list(map(int, data[2:]))
        if len(values) < m * n:
            # Incomplete grid, fallback to 0
            return 0
        grid = [values[i * n:(i + 1) * n] for i in range(m)]
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
