def solve(lst):
    """Flatten a possibly nested list of integers.
    The input is a list whose elements are either integers or lists (which may themselves be nested).
    Returns a flat list of all integers in the order they appear when traversed depth‑first left‑to‑right.
    """
    result = []
    stack = [iter(lst)]  # use iterator stack for depth‑first traversal without recursion limits
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            # Dive into the sub‑list
            stack.append(iter(item))
        else:
            # Assume any non‑list element should be treated as an int (or kept as is)
            result.append(item)
    return result

