def solve(n, edges):
    from heapq import heapify, heappush, heappop
    adj = [[] for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        adj[a].append(b)
        indeg[b]+=1
    heap = [i for i in range(n) if indeg[i]==0]
    heapify(heap)
    order=[]
    while heap:
        u=heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heappush(heap,v)
    if len(order)!=n:
        return []
    return order

