{"task_id": "T47", "code": "def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 and lowercase a-z for values 10-35. Negative numbers
    are prefixed with '-'.
    """
    if b < 2 or b > 36:
        raise ValueError("Base must be between 2 and 36 inclusive")
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))
