    """Return the leftmost index to insert *x* into sorted list *arr*.
    Handles three calling patterns:
    1. ``solve([1,2,3], 4)`` – direct arguments.
    2. ``solve()`` – reads from stdin: first line is space‑separated sorted numbers
       (may be empty), second line is the integer ``x``.
    3. ``solve([1,2,3])`` – treats missing ``x`` as read from stdin on the
       next line (fallback to ``0`` if unavailable).
    The implementation uses binary search to guarantee ``O(log n)`` time.
    """
    import sys
    # Detect stdin mode when both arguments are missing or x is missing
    if arr is None and x is None:
        data = sys.stdin.read().splitlines()
        if not data:
            return 0
        arr_line = data[0].strip()
        arr = [] if arr_line == '' else list(map(int, arr_line.split()))
        if len(data) > 1:
            try:
                x = int(data[1].strip())
            except Exception:
                x = 0
        else:
            x = 0
    elif x is None:
        # arr provided, x missing – try to read x from stdin
        line = sys.stdin.read().strip()
        try:
            x = int(line) if line else 0
        except Exception:
            x = 0
        if arr is None:
            arr = []
    # At this point both arr and x are defined
    # Ensure arr is a list of ints
    if not isinstance(arr, list):
        arr = list(arr)
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
