    # Levenshtein distance DP O(len(a)*len(b))
    n, m = len(a), len(b)
    # initialize DP table with two rows to save memory
    prev = list(range(m+1))
    for i in range(1, n+1):
        cur = [i] + [0]*m
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
