    Division truncates toward zero. Numbers may be negative (e.g., "-3")."""
    stack = []
    for t in tokens:
        # try to interpret as integer literal
        try:
            num = int(t)
            stack.append(num)
            continue
        except ValueError:
            pass  # not a literal, must be operator
        if t not in ('+', '-', '*', '/'):
            raise ValueError(f'Invalid token: {t}')
        b = stack.pop()
        a = stack.pop()
        if t == '+':
            res = a + b
        elif t == '-':
            res = a - b
        elif t == '*':
            res = a * b
        else:  # division, truncate toward zero
            # handle division by zero per Python semantics (will raise ZeroDivisionError)
            neg = (a < 0) ^ (b < 0)
            res = abs(a) // abs(b)
            if neg:
                res = -res
        stack.append(res)
    return stack[0]

